import{_ as t,o as a,c as s,a8 as i}from"./chunks/framework.DpsX1MbM.js";const m=JSON.parse('{"title":"Domino disaggregated performance findings","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/domino-disaggregated-performance.md","filePath":"sections/benchmarks/domino-disaggregated-performance.md","lastUpdated":1788846900000}'),r={name:"benchmarks/domino-disaggregated-performance.md"};function n(o,e,d,l,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="domino-disaggregated-performance-findings" tabindex="-1">Domino disaggregated performance findings <a class="header-anchor" href="#domino-disaggregated-performance-findings" aria-label="Permalink to &quot;Domino disaggregated performance findings&quot;">​</a></h1><p>This page preserves the measured tuning results from the Qwen3-8B Domino online-disaggregated investigation on one 8×H200 node: one patched SGLang capture server, seven FSDP draft trainers, and an approximately 1.1B-parameter Domino/DFlash-family draft. Treat these numbers as historical evidence for that hardware, model, dataset, and software revision, not as a current-release performance claim. Rerun the benchmark before extrapolating to another setup.</p><p>All throughput values below are total samples divided by total elapsed time over at least 390 seconds. Short, approximately 20-second windows were not stable because supply was bursty and varied by roughly 1.8×.</p><h2 id="headline" tabindex="-1">Headline <a class="header-anchor" href="#headline" aria-label="Permalink to &quot;Headline&quot;">​</a></h2><p>Configuration-only tuning took the 1-server + DP7 setup from <strong>28.8 to 50.1 samples/s (+74%)</strong>. The capture server reported 98% GPU utilization and 76% SM utilization; trainer GPUs reported 77–100% GPU utilization and 76–85% SM utilization. The model and default behavior were unchanged; every setting below is opt-in.</p><h2 id="best-measured-settings" tabindex="-1">Best measured settings <a class="header-anchor" href="#best-measured-settings" aria-label="Permalink to &quot;Best measured settings&quot;">​</a></h2><p>The canonical entry remains <code>specforge train -c YAML</code>. Repeat the same URL in the typed list to create multiple producer workers against one capture server; use distinct URLs to fan out across distinct servers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLONE_ON_FETCH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOADER_PREFETCH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOONCAKE_PROTOCOL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rdma</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOONCAKE_RDMA_DEVICES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mlx5_0,mlx5_1,mlx5_2,mlx5_3,mlx5_4,mlx5_5,mlx5_6,mlx5_7</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the external capture server with --mem-fraction-static 0.5, then run:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/configs/online/disaggregated/external/qwen3-8b-domino-disaggregated.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;deployment.disaggregated.server_urls=[&quot;http://127.0.0.1:30000&quot;,&quot;http://127.0.0.1:30000&quot;,&quot;http://127.0.0.1:30000&quot;,&quot;http://127.0.0.1:30000&quot;,&quot;http://127.0.0.1:30000&quot;,&quot;http://127.0.0.1:30000&quot;,&quot;http://127.0.0.1:30000&quot;,&quot;http://127.0.0.1:30000&quot;]&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  deployment.trainer.nproc_per_node=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  training.batch_size=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  training.accumulation_steps=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span></code></pre></div><p>GPU visibility and the external server&#39;s memory fraction remain deployment settings. See the <a href="./../basic_usage/disaggregated_training.html#multi-server-capture">disaggregated training guide</a> for the distinction between multiple capture servers and multiple workers driving one server.</p><h2 id="self-contained-one-server-dp7-topology" tabindex="-1">Self-contained one-server + DP7 topology <a class="header-anchor" href="#self-contained-one-server-dp7-topology" aria-label="Permalink to &quot;Self-contained one-server + DP7 topology&quot;">​</a></h2><p>The deleted self-contained shell&#39;s process topology is retained as a typed, managed-local recipe. One command owns Mooncake, a capture server on GPU 0, and seven trainer ranks on GPUs 1–7:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  examples/configs/online/disaggregated/managed-local/qwen3-8b-domino-1server-dp7-disaggregated.yaml</span></span></code></pre></div><p>The recipe records batch size 2, accumulation 8, and capture-server memory fraction 0.5. It intentionally creates one producer worker for its one owned server. The 50.1 samples/s result above used eight workers against one external server, so use the repeated-URL command in <strong>Best measured settings</strong> when reproducing that exact historical peak. <code>CLONE_ON_FETCH=0</code>, <code>LOADER_PREFETCH=2</code>, and hardware-specific RDMA settings remain opt-in runtime environment controls.</p><h2 id="what-each-setting-does" tabindex="-1">What each setting does <a class="header-anchor" href="#what-each-setting-does" aria-label="Permalink to &quot;What each setting does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th><th>Mechanism</th></tr></thead><tbody><tr><td>Repeat one URL eight times in <code>deployment.disaggregated.server_urls</code></td><td>Breaks the single-producer ceiling</td><td>Eight rollout workers take disjoint leases and issue blocking HTTP prefill calls concurrently to one server.</td></tr><tr><td><code>training.accumulation_steps=8</code></td><td>460 to approximately 280 ms/microstep</td><td>FSDP <code>no_sync</code> amortizes reduce-scatter across eight microsteps; communication fell to about 1 ms/microstep.</td></tr><tr><td><code>CLONE_ON_FETCH=0</code></td><td>Approximately 15 ms/batch lower</td><td>Mooncake <code>get()</code> already allocates a fresh tensor, so the defensive clone is redundant on this path.</td></tr><tr><td><code>LOADER_PREFETCH=2</code></td><td>Removes fetch latency from the measured train step</td><td>A background thread materializes up to two batches before the trainer consumes them.</td></tr><tr><td>External SGLang <code>--mem-fraction-static 0.5</code></td><td>Server memory fell from 126 GB to about 78 GB</td><td>The default 0.85 reservation held KV-cache memory that this capture-only server did not need.</td></tr></tbody></table><p>The server-side capture patch also kept hidden-state slices on GPU and used one <code>torch.cat</code> plus one D2H copy per request instead of a per-prefill-batch unpinned copy. In this run, capture D2H fell from 5–8 ms/sample to approximately 3.8 ms/sample.</p><h2 id="the-pipeline-is-a-supply-demand-seesaw" tabindex="-1">The pipeline is a supply/demand seesaw <a class="header-anchor" href="#the-pipeline-is-a-supply-demand-seesaw" aria-label="Permalink to &quot;The pipeline is a supply/demand seesaw&quot;">​</a></h2><p>At 50 samples/s the system was supply-bound: one capture server only just fed seven trainers, loader waits were approximately 40 ms/batch, and producer in-flight depth stayed low. The GPU split was therefore a real trade-off:</p><table tabindex="0"><thead><tr><th>Split</th><th>Throughput</th><th>Regime</th></tr></thead><tbody><tr><td><strong>1 server + 7 trainers</strong></td><td><strong>50.1/s</strong></td><td>Supply-bound; best measured split</td></tr><tr><td>2 servers + 6 trainers, batch 2</td><td>39.0/s</td><td>Demand-bound; only six trainers</td></tr><tr><td>2 servers + 6 trainers, batch 8</td><td>39.5/s</td><td>Demand-bound; larger batch did not help</td></tr></tbody></table><p>Each trainer GPU consumed approximately 7 samples/s, while one server supplied approximately 52–57 samples/s. Seven trainers, about 50 samples/s of demand, were almost exactly balanced by one server. Trading away a trainer for a second server lost more demand than it added supply on this eight-GPU allocation.</p><h2 id="bigger-batches-did-not-help" tabindex="-1">Bigger batches did not help <a class="header-anchor" href="#bigger-batches-did-not-help" aria-label="Permalink to &quot;Bigger batches did not help&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Batch</th><th>Accumulation</th><th>Throughput</th><th>Trainer memory</th><th>Trainer utilization</th></tr></thead><tbody><tr><td><strong>2</strong></td><td><strong>8</strong></td><td><strong>50.1/s</strong></td><td>45 GB (about 31%)</td><td>77–100%</td></tr><tr><td>4</td><td>4</td><td>47.5/s</td><td>65 GB (about 45%)</td><td>64–99%</td></tr><tr><td>8</td><td>2</td><td>47.2/s</td><td>113 GB (about 79%)</td><td>100%</td></tr></tbody></table><p>Memory climbed with batch size, but throughput fell. The larger batch made each fetch roughly four times heavier (<code>get_ms</code> rose from about 20 to 90) while per-sample compute stayed flat. Low trainer memory in the best configuration was efficient rather than evidence of a stall: the trainer was compute-bound at approximately 44% measured MFU.</p><h2 id="why-per-sample-trainer-demand-is-low" tabindex="-1">Why per-sample trainer demand is low <a class="header-anchor" href="#why-per-sample-trainer-demand-is-low" aria-label="Permalink to &quot;Why per-sample trainer demand is low&quot;">​</a></h2><p>The benchmark&#39;s synchronized step measurements at batch size two were:</p><table tabindex="0"><thead><tr><th><code>num_anchors</code></th><th>Forward</th><th>Backward</th><th>Optimizer</th><th>Data wait</th></tr></thead><tbody><tr><td>256, recipe default</td><td>approximately 88 ms</td><td>approximately 150 ms</td><td>1.3 ms</td><td>approximately 40 ms (14%)</td></tr><tr><td>64</td><td>approximately 43 ms</td><td>approximately 58 ms</td><td>1.3 ms</td><td>approximately 145 ms (38%), supply-starved</td></tr></tbody></table><p>Domino/DFlash training expands every sample to <code>num_anchors × block_size</code>: 256 × 16 = 4096 draft positions independent of input sequence length. Each position passes through the five-layer draft and a full 151,936-vocabulary head. A fit of these measurements gives approximately 53 ms fixed work plus 0.73 ms per anchor, so the anchor expansion accounts for roughly 78% of the 240 ms microstep at 256 anchors.</p><p>Reducing anchors is therefore not a free throughput optimization. At 256 anchors the run delivered approximately 2,130 anchor updates/s, versus about 1,280 at 64 anchors. Fewer anchors raised sequences/s but reduced training signal/s by roughly 40%, while putting more pressure on the already supply-bound capture server. Treat <code>num_anchors</code> as a quality and data-efficiency choice validated against acceptance length; the checked-in recipe keeps 256.</p><h2 id="mfu-and-flops" tabindex="-1">MFU and FLOPs <a class="header-anchor" href="#mfu-and-flops" aria-label="Permalink to &quot;MFU and FLOPs&quot;">​</a></h2><p>The isolated trainer microbenchmark used <code>bench_domino_mfu.py</code>, BF16, real Qwen3-8B Domino shapes, <code>num_anchors=256</code>, sequence length 768, CUDA event timing, and <code>torch.utils.flop_counter</code>:</p><table tabindex="0"><thead><tr><th>Batch</th><th>Step</th><th>Per sample</th><th>FLOP/sample, forward + backward</th><th>Achieved</th><th>MFU</th><th>Peak memory</th></tr></thead><tbody><tr><td>2</td><td>211 ms</td><td>105.6 ms</td><td>approximately 45 T</td><td>430 TFLOP/s</td><td><strong>43.5%</strong></td><td>25 GB</td></tr><tr><td>4</td><td>416 ms</td><td>103.9 ms</td><td>approximately 45 T</td><td>437 TFLOP/s</td><td>44.1%</td><td>46 GB</td></tr><tr><td>8</td><td>836 ms</td><td>104.6 ms</td><td>approximately 45 T</td><td>434 TFLOP/s</td><td>43.9%</td><td>87 GB</td></tr></tbody></table><p>The approximately 1.1B draft was compute-bound, not stalled. Per-sample time was flat across batch sizes, and memory grew by roughly 10 GB/sample. One sample cost approximately 45 TFLOP for forward plus backward—about nine times a normal 1.1B forward—because of the 256-anchor expansion and two full-vocabulary paths.</p><p>Target prefill was estimated at a similar 43% MFU. At 50 samples/s the server logged approximately 27,000 tokens/s over 1,080 batches, with an average prompt of about 550 tokens. For the 8B target, <code>2 × parameters × tokens/s</code> is about 430 TFLOP/s. This estimate excludes attention FLOPs and the five auxiliary capture layers.</p><h2 id="remaining-ceilings" tabindex="-1">Remaining ceilings <a class="header-anchor" href="#remaining-ceilings" aria-label="Permalink to &quot;Remaining ceilings&quot;">​</a></h2><ol><li>Supply at approximately 50 samples/s was prefill-compute-bound, not sink-bound. With at least eight producer workers, target prefill ran nearly continuously at about 27,000 tokens/s. The Mooncake sink sustained roughly 44–57 samples/s and was the next ceiling, not the measured one. Potential supply improvements include higher prefill MFU, larger prefill batches, and lighter auxiliary-state extraction/D2H; a second inference GPU was worse on this fixed eight-GPU split.</li><li>Trainer demand at approximately 50 samples/s was also compute-bound near 44% MFU. Raising trainer MFU would reduce trainer GPU cost, but could not improve end-to-end throughput until capture supply increased. Reducing <code>num_anchors</code> would change training signal and is not an equivalent systems optimization.</li></ol><h2 id="profiling-controls" tabindex="-1">Profiling controls <a class="header-anchor" href="#profiling-controls" aria-label="Permalink to &quot;Profiling controls&quot;">​</a></h2><p>Production runs expose the typed <code>profiling</code> configuration (<code>enabled</code>, <code>start_step</code>, <code>num_steps</code>, and <code>record_shapes</code>) for bounded PyTorch traces on trainer ranks. The component timers used to collect this benchmark were temporary measurement instrumentation and are not runtime environment APIs. <code>FSDP_SHARDING=NO_SHARD</code> remains available for controlled sharding comparisons.</p>`,37)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
